use vstd::prelude::*;

verus! {

fn append(v: &Vec<u64>, elem: u64) -> (out: Vec<u64>)
    requires
        v.len() <= 100,
    ensures
        // (1) length increases by 1
        out.len() == v.len() + 1,
        // (2) prefix is preserved
        forall|i: int| 0 <= i < v.len() ==> out[i] == v[i],
        // (3) last element is the appended elem
        out[v.len() as int] == elem,
{
    let mut out: Vec<u64> = Vec::new();

    let mut i: usize = 0;
    while i < v.len()
        invariant
            v.len() <= 100,
            i <= v.len(),
            out.len() == i,
            forall|j: int| 0 <= j < i ==> out[j] == v[j],
        decreases
            v.len() - i,
    {
        out.push(v[i]);
        i = i + 1;
    }

    // Now out is a copy of v
    assert(out.len() == v.len());
    assert(forall|j: int| 0 <= j < v.len() ==> out[j] == v[j]);

    out.push(elem);

    // After pushing elem, length is v.len() + 1 and last element is elem
    assert(out.len() == v.len() + 1);
    assert(out[v.len() as int] == elem);

    out
}

} // verus!

